// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address newManager) public {
        vm.assume(newManager != address(0) && newManager != address(c));
        c.file("investmentManager", newManager);
        address stored = address(c.investmentManager());
        assertTrue(stored == newManager);
    }
}

